"""Dev-only independent reference model of the PROTOCOL.md collector semantics.
Used solely to cross-check project/solver.py during development."""
import hashlib, struct, sys, zlib
sys.path.insert(0, '/workspace/project')
from wire import NAMES, emissions, packet, MASK

class Model:
    def __init__(self, prim, mode, root, K, D, N, start):
        self.prim, self.mode, self.root = prim, mode, root
        self.K, self.D, self.N, self.start = K, D, N, start
        self.slots = {}                       # p -> {'mask','agg','raw'}
        self.b = 0
        self.R = [0]*4; self.sent=[0]*4; self.ackd=[0]*4; self.U=[0]*4
        self.repeat=[False]*4
        self.rx_data=self.rx_ack=self.tx_data=self.tx_ack=0
        self.accepted=self.duplicates=self.blocked=self.stale=0
        self.invalid_wire=self.invalid_endpoint=self.ack_ignored=0
        self.failed_sends=0
        self.budget=-1
        self.tape=hashlib.sha256(); self.packets=0; self.wire_bytes=0
        self.trace=[]; self.limit=0

    # ---- helpers ----
    def req_mask(self):
        return (1<<self.root) if self.prim=='broadcast' else 0xF
    def complete(self, s):
        return (s['mask'] & self.req_mask()) == self.req_mask()
    def out_len(self, d):
        p=self.prim;K=self.K
        return {'allreduce':K,'reduce':K if d==self.root else 0,
                'broadcast':0 if d==self.root else K,'barrier':1,
                'allgather':3*K,'reducescatter':K//4}[p]
    def ord_excl(self,d,s):
        return [r for r in range(4) if r!=d].index(s)
    def rank_from_ord(self,d,o):
        return [r for r in range(4) if r!=d][o]
    def out_map(self,d,q):
        if self.prim=='allgather':
            return q//3, self.rank_from_ord(d, q%3)
        if self.prim=='reducescatter':
            return d*(self.K//4)+q, -1
        if self.prim=='barrier':
            return 0, -1
        return q, -1
    def safe2(self, r, p):
        pr=self.prim
        if pr=='allreduce': return self.ackd[r] > p
        if pr=='barrier': return self.ackd[r] > 0
        if pr=='reduce': return self.ackd[self.root] > p
        if pr=='broadcast': return all(self.ackd[d] > p for d in range(4) if d!=self.root)
        if pr=='reducescatter':
            blk=self.K//4; return self.ackd[p//blk] > p%blk
        if pr=='allgather':
            return all(self.ackd[d] > 3*p+self.ord_excl(d,r) for d in range(4) if d!=r)
        return True
    def outs_acked(self,p):
        pr=self.prim
        if pr=='allreduce': return all(self.ackd[d] > p for d in range(4))
        if pr=='reduce': return self.ackd[self.root] > p
        if pr=='broadcast': return all(self.ackd[d] > p for d in range(4) if d!=self.root)
        if pr=='barrier': return all(self.ackd[d] > 0 for d in range(4))
        if pr=='allgather': return all(self.ackd[d] > 3*p+2 for d in range(4))
        if pr=='reducescatter':
            blk=self.K//4; return self.ackd[p//blk] > p%blk
        return True
    def retireable(self,p):
        s=self.slots.get(p)
        if not s or not self.complete(s): return False
        if not self.outs_acked(p): return False
        req=self.req_mask()
        return all(self.U[r] > p for r in range(4) if req>>r & 1)
    def e_prefix(self,r):
        n=0
        while n < self.R[r] and (self.mode==3 or self.safe2(r,n)): n+=1
        return n

    # ---- emission ----
    def emit(self, rank, frame):
        if self.budget==0:
            self.failed_sends+=1
            return False
        if self.budget>0: self.budget-=1
        self.tape.update(bytes((rank,))+struct.pack('<I',len(frame))+frame)
        self.packets+=1; self.wire_bytes+=len(frame)
        if len(self.trace)<self.limit:
            self.trace.append({'rank':rank,'hex':frame.hex()})
        return True

    def build_ack(self,r,e):
        return packet(r,(self.start+e-1)&MASK,ack=True,outgoing=True)
    def build_result(self,d,q):
        p,src=self.out_map(d,q)
        s=self.slots.get(p)
        psn=(self.start+q)&MASK
        if self.prim=='barrier':
            return packet(d,psn,b'',outgoing=True)
        if self.prim in ('broadcast','allgather'):
            sr = src if src>=0 else self.root
            return packet(d,psn,s['raw'][sr],outgoing=True)
        pay=b''.join(struct.pack('!I',w) for w in s['agg'])
        return packet(d,psn,pay,outgoing=True)

    # ---- service ----
    def service(self, retry_rank=-1):
        for r in range(4):
            e=self.e_prefix(r)
            if e>0 and (e>self.U[r] or self.repeat[r]):
                if not self.emit(r, self.build_ack(r,e)):
                    return self.retire()
                self.U[r]=e; self.repeat[r]=False
        if retry_rank>=0:
            for q in range(self.ackd[retry_rank], self.sent[retry_rank]):
                if not self.emit(retry_rank, self.build_result(retry_rank,q)):
                    return self.retire()
        for d in range(4):
            while self.sent[d] < self.out_len(d):
                p,src=self.out_map(d,self.sent[d])
                s=self.slots.get(p)
                if not s or not self.complete(s): break
                if not self.emit(d, self.build_result(d,self.sent[d])):
                    return self.retire()
                self.sent[d]+=1
        self.retire()

    def retire(self):
        while self.b < self.K and self.retireable(self.b):
            self.slots.pop(self.b, None)
            self.b+=1

    # ---- ingress ----
    def wire_check(self, f):
        L=len(f)
        if L<58: return None
        if f[12:14]!=b'\x08\x00': return None
        if f[14]!=0x45: return None
        if f[23]!=17: return None
        if struct.unpack('!H',f[20:22])[0] not in (0x0000,0x4000): return None
        tot=sum(struct.unpack('!10H',f[14:34]))
        while tot>>16: tot=(tot&65535)+(tot>>16)
        if tot!=0xffff: return None
        ip_total=struct.unpack('!H',f[16:18])[0]
        if L!=ip_total+14: return None
        if ip_total<44: return None
        if f[34:38]!=b'\x12\xb7\x12\xb7': return None
        if struct.unpack('!H',f[38:40])[0]!=ip_total-20: return None
        if f[40:42]!=b'\x00\x00': return None
        op=f[42]
        if op not in (4,0x11): return None
        if f[43]!=0: return None
        if f[44:46]!=b'\xff\xff': return None
        qpn=struct.unpack('!I',f[46:50])[0]
        if qpn>>24: return None
        apsn=struct.unpack('!I',f[50:54])[0]
        psn=apsn&0xffffff
        if op==4:
            if apsn>>24!=0x80: return None
            if ip_total!=44+4*self.D: return None
            payload=f[54:54+4*self.D]
            is_ack=False
        else:
            if apsn>>24!=0: return None
            if ip_total!=48: return None
            if f[54]!=0x1f: return None
            if struct.unpack('!I',f[54:58])[0]&0xffffff != (psn+1)&0xffffff:
                return None
            payload=None; is_ack=True
        crc_in=bytearray(b'\xff'*8+f[14:-4])
        crc_in[9]=255; crc_in[16]=255
        crc_in[18:20]=b'\xff\xff'; crc_in[34:36]=b'\xff\xff'; crc_in[40]=255
        if struct.unpack('<I',f[-4:])[0]!=zlib.crc32(bytes(crc_in)):
            return None
        return (is_ack, psn, payload)

    def endpoint_ok(self, rank, f, is_ack):
        hostmac=bytes((2,0,0,0,0,rank+1)); swmac=bytes((2,1,0,0,0,rank+1))
        if f[:6]!=swmac or f[6:12]!=hostmac: return False
        hostip=bytes((10,0,0,rank+1)); swip=bytes((10,0,0,101+rank))
        if f[26:30]!=hostip or f[30:34]!=swip: return False
        if struct.unpack('!I',f[46:50])[0]&0xffffff != 0x200+rank: return False
        return True

    def ingress(self, rank, f):
        chk=self.wire_check(f)
        if chk is None:
            self.invalid_wire+=1; return
        is_ack,psn,payload=chk
        if not self.endpoint_ok(rank,f,is_ack):
            self.invalid_endpoint+=1; return
        if not is_ack:
            if self.prim=='broadcast' and rank!=self.root:
                self.invalid_endpoint+=1; return
            p=(psn-self.start)&0xffffff
            if p>=self.K:
                self.invalid_endpoint+=1; return
            self.rx_data+=1
            if p<self.b:
                self.stale+=1; self.repeat[rank]=True
            elif p>=min(self.K,self.b+self.N):
                self.blocked+=1
            else:
                s=self.slots.setdefault(p,{'mask':0,'agg':[0]*self.D,'raw':{}})
                if s['mask']>>rank & 1:
                    self.duplicates+=1; self.repeat[rank]=True
                else:
                    s['mask']|=1<<rank
                    if self.prim=='allgather':
                        s['raw'][rank]=payload
                    elif self.prim=='broadcast':
                        s['raw'][rank]=payload
                    elif self.prim!='barrier':
                        for j in range(self.D):
                            s['agg'][j]=(s['agg'][j]+struct.unpack('!I',payload[4*j:4*j+4])[0])&0xffffffff
                    self.accepted+=1
                    for r in range(4):
                        while self.R[r]<self.K:
                            t=self.slots.get(self.R[r])
                            if not t or not (t['mask']>>r & 1): break
                            self.R[r]+=1
        else:
            self.rx_ack+=1
            plen=(psn-self.start+1)&0xffffff
            if 0<plen and plen>self.ackd[rank] and plen<=self.sent[rank]:
                self.ackd[rank]=plen
            else:
                self.ack_ignored+=1
        self.service(-1)

    # ---- certificate ----
    def digest(self):
        def fb(h,v): return ((h^v)*1099511628211)&0xFFFFFFFFFFFFFFFF
        h=14695981039346656037
        for p in range(self.b, min(self.K,self.b+self.N)):
            s=self.slots.get(p)
            if not s or s['mask']==0: continue
            for byte in struct.pack('<Q',p): h=fb(h,byte)
            h=fb(h,s['mask']); h=fb(h,1 if self.complete(s) else 0)
            if self.prim=='allgather':
                for r in range(4):
                    v=s['raw'].get(r)
                    h=fb(h,1 if v is not None else 0)
                    if v is not None:
                        for byte in v: h=fb(h,byte)
            elif self.prim=='broadcast':
                for byte in s['raw'][self.root]: h=fb(h,byte)
            elif self.prim!='barrier':
                for w in s['agg']:
                    for byte in struct.pack('<I',w): h=fb(h,byte)
        return format(h,'016x')

    def snapshot(self):
        state=[0]*32
        state[0]=self.b; state[1]=sum(1 for p in self.slots if self.slots[p]['mask'])
        state[2:6]=self.R; state[6:10]=self.sent; state[10:14]=self.ackd; state[14:18]=self.U
        vals=[self.rx_data,self.rx_ack,self.tx_data,self.tx_ack,self.accepted,
              self.duplicates,self.blocked,self.stale,self.invalid_wire,
              self.invalid_endpoint,self.ack_ignored,self.failed_sends,0]
        state[18:31]=vals
        return {'state':state,'buffer':self.digest(),
                'wire_sha256':self.tape.hexdigest(),
                'packets':self.packets,'bytes':self.wire_bytes}

def run(case):
    m=Model(case['primitive'],case['mode'],case['root'],case['segments'],
            case['words'],case['capacity'],case['start'])
    m.limit=case.get('trace',0)
    snaps=[]
    for name,arg,frame in emissions(case):
        if name=='wire': m.ingress(arg,frame)
        elif name=='flush': m.service(-1)
        elif name=='retry':
            m.repeat[arg]=True; m.service(arg)
        elif name=='budget': m.budget=arg
        elif name=='snap': snaps.append({'tag':arg,**m.snapshot()})
        else: raise ValueError(name)
    out=m.snapshot()
    return {**out,'snapshots':snaps,'trace':m.trace}
